function obtenerEtiqueta() {
  const candidatos = ['Marcar area Hunting', 'Marcar area Integraciones', 'Marcar area Engagement'];
  for (const nombre of candidatos) {
    try {
      const item = $(nombre).item;
      if (item) return item.json;
    } catch (e) {}
  }
  return {};
}

function parseTranscripcion(raw) {
  const lineas = (raw || '').split('\n').map(l => l.trim()).filter(Boolean);
  const idxAsistentes = lineas.findIndex(l => /^(asistentes|attendees)$/i.test(l));
  const idxTranscripcion = lineas.findIndex(l => /^(transcripci[oó]n|transcript)$/i.test(l));

  const participantes = (idxAsistentes >= 0 && idxTranscripcion > idxAsistentes)
    ? lineas.slice(idxAsistentes + 1, idxTranscripcion).join(', ')
    : '';

  let cuerpo = idxTranscripcion >= 0 ? lineas.slice(idxTranscripcion + 1) : lineas;
  const idxFin = cuerpo.findIndex(l => /reuni[oó]n finaliz[oó]|call ended|meeting ended/i.test(l));
  if (idxFin >= 0) cuerpo = cuerpo.slice(0, idxFin);
  cuerpo = cuerpo.filter(l => !/se gener[oó] autom[aá]ticamente|automatically generated/i.test(l));

  return { participantes, transcripcion: cuerpo.join('\n') };
}

const etiqueta = obtenerEtiqueta();
const actual = $input.first().json;
const parsed = parseTranscripcion(actual.texto_extraido || '');

return [{ json: {
  area: etiqueta.area || '',
  slackChannel: etiqueta.slackChannel || '',
  evento_id: 'drive-' + (actual.id || etiqueta.id || Date.now()),
  titulo: actual.name || etiqueta.name || 'Reunion sin titulo',
  participantes: parsed.participantes,
  fin: etiqueta.modifiedTime || etiqueta.createdTime || new Date().toISOString(),
  transcripcion_texto: parsed.transcripcion
} }];

// Roster de ejecutivos comerciales de Xtract, tal como figuran en el CRM.
// Editar ACA si alguien entra o sale del equipo (unico lugar).
const EJECUTIVOS = [
  { nombre: 'Nicolás Gonzalez', cuentas: 394 },
  { nombre: 'Juan Alvarez', cuentas: 127 },
  { nombre: 'Tomas Marconi', cuentas: 60 },
  { nombre: 'Jesús De Gruttola', cuentas: 26 },
  { nombre: 'Damian Deggeller', cuentas: 16 },
  { nombre: 'Matías Febré', cuentas: 3 },
  { nombre: 'Wenceslao Hoepner', cuentas: 1 },
  { nombre: 'Jesús Soria', cuentas: 0 }
];

// Particulas que no aportan a la identidad del nombre.
const PARTICULAS = ['de', 'del', 'la', 'las', 'los', 'da', 'di', 'van', 'von', 'san'];

// Los notetakers entran como un asistente mas: hay que descartarlos.
const BOTS = /notetaker|fathom|otter|fireflies|companion|read ai|grabador|transcriptor|\bbot\b/i;

// Normalizacion estandar del repo: NFD, sin acentos, minusculas, espacios colapsados.
function normKey(s) {
  return (s || '').toString()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function tokens(s) {
  return normKey(s).split(' ').filter(t => t && PARTICULAS.indexOf(t) === -1);
}

// Coincide si TODOS los tokens del ejecutivo estan en el candidato.
// Asi "Juan Alvarez" matchea "Juan Alvarez (Xtract)" pero no "Juan Perez".
function coincide(ejecutivo, candidato) {
  const tokensEjecutivo = tokens(ejecutivo);
  const tokensCandidato = tokens(candidato);
  if (tokensEjecutivo.length < 2 || !tokensCandidato.length) return false;
  return tokensEjecutivo.every(t => tokensCandidato.indexOf(t) !== -1);
}

// Nombres de la seccion "Asistentes" (separados por coma).
function listarAsistentes(str) {
  return (str || '')
    .split(',')
    .map(s => s.trim())
    .filter(s => s && !BOTS.test(s));
}

// Quien habla en el cuerpo: lineas con formato "Nombre Apellido: texto".
function contarIntervenciones(texto) {
  const conteo = {};
  (texto || '').split('\n').forEach((linea) => {
    const m = linea.match(/^([^:]{2,60}):\s/);
    if (!m) return;
    const nombre = m[1].trim();
    if (BOTS.test(nombre)) return;
    conteo[nombre] = (conteo[nombre] || 0) + 1;
  });
  return conteo;
}

const salida = [];

$input.all().forEach((item) => {
  const meta = item.json || {};
  const asistentes = listarAsistentes(meta.participantes);
  const intervenciones = contarIntervenciones(meta.transcripcion_texto);
  const hablantes = Object.keys(intervenciones);

  const detectados = [];
  EJECUTIVOS.forEach((ej) => {
    const enAsistentes = asistentes.some(a => coincide(ej.nombre, a));
    const hablante = hablantes.find(h => coincide(ej.nombre, h));
    if (!enAsistentes && !hablante) return;
    detectados.push({
      nombre: ej.nombre,
      cuentas: ej.cuentas,
      en_asistentes: enAsistentes,
      intervenciones: hablante ? intervenciones[hablante] : 0
    });
  });

  // El principal es el que mas hablo; si nadie hablo, el de mas cuentas asignadas.
  detectados.sort((a, b) => (b.intervenciones - a.intervenciones) || (b.cuentas - a.cuentas));

  const nombres = detectados.map(d => d.nombre);

  salida.push({ json: Object.assign({}, meta, {
    ejecutivo: nombres[0] || 'Sin identificar',
    ejecutivos: nombres.join(', '),
    ejecutivos_detalle: detectados,
    ejecutivo_identificado: detectados.length > 0
  }) });
});

return salida;

