const salida = [];

$input.all().forEach((item) => {
  const meta = item.json || {};
  const transcripcion = meta.transcripcion_texto || '';
  if (!transcripcion.trim()) return;
  const transcripcionRecortada = transcripcion.slice(0, MAX);

  const prompt = 'Sos un asistente que ayuda a preparar el seguimiento de una reunion comercial en espanol neutro.\n\n' +
    'Trabajas para Xtract. Esto es lo que YA SABEMOS de nuestro propio producto:\n\n' +
    '=== BASE DE CONOCIMIENTO ===\n' + BASE_CONOCIMIENTO + '\n=== FIN BASE DE CONOCIMIENTO ===\n\n' +
    'Reunion: ' + (meta.titulo || '') + '\n' +
    'Area: ' + (meta.area || '') + '\n' +
    'Participantes: ' + (meta.participantes || '') + '\n' +
    'Ejecutivo comercial de Xtract en la reunion: ' + (meta.ejecutivo || 'sin identificar') + '\n\n' +
    'TRANSCRIPCION:\n' + transcripcionRecortada + '\n\n' +
    'El objetivo NO es una minuta interna. Es un mensaje LISTO PARA ENVIARLE AL CLIENTE apenas termina la reunion. Completa estos campos:\n' +
    '- recap: 2 o 3 oraciones en tono cordial recapitulando lo hablado, escritas como si se las mandaramos directamente al cliente (sin jerga interna, sin nombrar procesos internos nuestros).\n' +
    '- informacion_necesaria: bullets con la informacion que necesitamos QUE EL CLIENTE NOS PASE para avanzar. Array vacio si no quedo nada pendiente de pedir; un array vacio es mejor que un pedido inventado o que uno que ya sabemos responder.\n' +
    '- proximo_paso: una frase con el proximo paso acordado con el cliente (por ejemplo coordinar una segunda reunion, y la fecha si se menciono).\n\n' +
    'REGLAS OBLIGATORIAS:\n' + REGLAS + '\n\n' +
    'Se concreto y basate solo en lo que esta en la transcripcion y en la base de conocimiento. No inventes nada.';

  salida.push({ json: {
    area: meta.area,
    slackChannel: meta.slackChannel,
    evento_id: meta.evento_id,
    titulo: meta.titulo,
    fin: meta.fin,
    participantes: meta.participantes,
    ejecutivo: meta.ejecutivo,
    ejecutivos: meta.ejecutivos,
