    prompt: prompt
  } });
});

return salida;

const FOLDER_ID = '1zR3fHtej1NN0NF7TfABp_YtNyGgYOWTS';

function escapeHtml(s) {
  return (s || '').toString()
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function listToHtml(items) {
  if (!items || !items.length) return '<p>Nada pendiente de pedir.</p>';
  return '<ul>' + items.map(i => '<li>' + escapeHtml(i) + '</li>').join('') + '</ul>';
}

function listToPlano(items) {
  if (!items || !items.length) return '(nada pendiente de pedir)';
  return items.map(i => '- ' + i).join('\n');
}

const meta = $('Armar prompt de la minuta').item.json;
const j = ($input.first().json) || {};
const minuta = j.output || j;

const recap = minuta.recap || '';
const informacionNecesaria = minuta.informacion_necesaria || [];
const proximoPaso = minuta.proximo_paso || 'Sin proximo paso definido';

const ejecutivo = meta.ejecutivo || 'Sin identificar';
const ejecutivosTodos = meta.ejecutivos || '';

// Si hubo mas de un ejecutivo en la llamada, se listan todos entre parentesis.
const ejecutivoLinea = (ejecutivosTodos && ejecutivosTodos !== ejecutivo)
  ? ejecutivo + ' (tambien presentes: ' + ejecutivosTodos.split(', ').filter(n => n !== ejecutivo).join(', ') + ')'
  : ejecutivo;

const html = '<html><body>' +
  '<h2>Seguimiento - ' + escapeHtml(meta.titulo || 'Reunion') + '</h2>' +
  '<p><b>Ejecutivo comercial:</b> ' + escapeHtml(ejecutivoLinea) + '</p>' +
  '<p><b>Area:</b> ' + escapeHtml(meta.area || '') + '</p>' +
  '<h3>Mensaje para el cliente</h3><p>' + escapeHtml(recap) + '</p>' +
  '<h3>Informacion que necesitamos que nos pasen</h3>' + listToHtml(informacionNecesaria) +
  '<h3>Proximo paso</h3><p>' + escapeHtml(proximoPaso) + '</p>' +
  '</body></html>';

const minutaTexto = 'Ejecutivo comercial: ' + ejecutivoLinea +
  '\n\nMensaje para el cliente: ' + recap +
  '\n\nInformacion que necesitamos que nos pasen:\n' + listToPlano(informacionNecesaria) +
  '\n\nProximo paso: ' + proximoPaso;

const nombreArchivo = 'Seguimiento - ' + (meta.titulo || 'Reunion') + ' - ' + new Date().toISOString().slice(0, 10);

const metadata = {
  name: nombreArchivo,
  parents: [FOLDER_ID],
  mimeType: 'application/vnd.google-apps.document'
};

const boundary = 'n8n_minuta_boundary_' + Date.now();

const multipartBody =
  '--' + boundary + '\r\n' +
  'Content-Type: application/json; charset=UTF-8\r\n\r\n' +
  JSON.stringify(metadata) + '\r\n' +
  '--' + boundary + '\r\n' +
  'Content-Type: text/html; charset=UTF-8\r\n\r\n' +
  html + '\r\n' +
  '--' + boundary + '--';

return [{ json: {
  area: meta.area,
  slackChannel: meta.slackChannel,
  evento_id: meta.evento_id,
  titulo: meta.titulo,
  fin: meta.fin,
  participantes: meta.participantes,
  ejecutivo: ejecutivo,
  ejecutivos: ejecutivosTodos,
  ejecutivoLinea: ejecutivoLinea,
  ejecutivo_identificado: meta.ejecutivo_identificado === true,
  recap: recap,
  informacionNecesaria: informacionNecesaria,
  proximoPaso: proximoPaso,
  minutaTexto: minutaTexto,
  boundary: boundary,
  multipartBody: multipartBody
} }];

const datos = $('Armar HTML de la minuta').item.json;
const actual = $input.first().json || {};
const docId = actual.id || '';
const docLink = docId ? 'https://docs.google.com/document/d/' + docId + '/edit' : '';

function bulletsSlack(items) {
  if (!items || !items.length) return '(nada pendiente de pedir)';
  return items.map(i => '• ' + i).join('\n');
}

const fecha = datos.fin ? new Date(datos.fin) : new Date();
const dd = String(fecha.getDate()).padStart(2, '0');
const mm = String(fecha.getMonth() + 1).padStart(2, '0');

const ejecutivoLinea = datos.ejecutivoLinea || datos.ejecutivo || 'Sin identificar';
const iconoEjecutivo = datos.ejecutivo_identificado ? ':bust_in_silhouette:' : ':warning:';

const texto = ':envelope: *Mensaje listo para el cliente - ' + (datos.titulo || 'Reunion') + '*\n' +
  '_' + (datos.area || '') + ' | ' + dd + '/' + mm + '_\n' +
  iconoEjecutivo + ' *Ejecutivo:* ' + ejecutivoLinea + '\n\n' +
  datos.recap + '\n\n' +
  '*Necesitamos que nos pasen:*\n' + bulletsSlack(datos.informacionNecesaria) + '\n\n' +
  '*Proximo paso:* ' + datos.proximoPaso +
  (docLink ? '\n\n:page_facing_up: <' + docLink + '|Ver documento completo>' : '');

return [{ json: {
  area: datos.area,
  slackChannel: datos.slackChannel,
  evento_id: datos.evento_id,
  titulo: datos.titulo,
  fin: datos.fin,
  participantes: datos.participantes,
  ejecutivo: datos.ejecutivo,
  ejecutivos: datos.ejecutivos,
  slack_message: texto,
  minuta: datos.minutaTexto,
  doc_link: docLink,
  fecha_procesado: new Date().toISOString()
} }];

const AREAS = {
  Hunting: { slackChannel: 'C_HUNTING' },
  Integraciones: { slackChannel: 'C_INTEGRACIONES' },
  Engagement: { slackChannel: 'C_ENGAGEMENT' }
};

function parseTranscripcion(raw) {
  const lineas = (raw || '').split('\n').map(l => l.trim()).filter(Boolean);
  const idxAsistentes = lineas.findIndex(l => /^(asistentes|attendees)$/i.test(l));
  const idxTranscripcion = lineas.findIndex(l => /^(transcripci[oó]n|transcript)$/i.test(l));

  const titulo = idxAsistentes > 0 ? lineas.slice(0, idxAsistentes).join(' ') : (lineas[0] || 'Reunion sin titulo');
  const participantes = (idxAsistentes >= 0 && idxTranscripcion > idxAsistentes)
    ? lineas.slice(idxAsistentes + 1, idxTranscripcion).join(', ')
    : '';

  let cuerpo = idxTranscripcion >= 0 ? lineas.slice(idxTranscripcion + 1) : lineas;
  const idxFin = cuerpo.findIndex(l => /reuni[oó]n finaliz[oó]|call ended|meeting ended/i.test(l));
  if (idxFin >= 0) cuerpo = cuerpo.slice(0, idxFin);
  cuerpo = cuerpo.filter(l => !/se gener[oó] autom[aá]ticamente|automatically generated/i.test(l));

  return { titulo, participantes, transcripcion: cuerpo.join('\n') };
}

const item = $input.first().json;
const area = item.area || '';
const conf = AREAS[area] || {};
const parsed = parseTranscripcion(item.transcripcion_completa || '');

return [{ json: {
  area,
  slackChannel: conf.slackChannel || '',
  evento_id: 'manual-' + Date.now(),
  titulo: parsed.titulo,
  participantes: parsed.participantes,
  fin: new Date().toISOString(),
  transcripcion_texto: parsed.transcripcion
} }];
